fn solve(input: Vec<char>) -> Vec<char> {
    // Get the first two characters (guaranteed to be ASCII digits)
    let first_char = input[0];
    let second_char = input[1];
    
    // Helper function to map digit character to its good count
    fn good_count(digit: char) -> u8 {
        match digit {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // This case shouldn't happen per problem constraints
        }
    }
    
    // Calculate the product
    let product = good_count(first_char) as u32 * good_count(second_char) as u32;
    
    // Convert product to string and then to vector of chars
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}